
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type: "normal",
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    ClearState: function () {
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx + this._reelIdx * 10;
    },

    setType(type) {
        this._type = type;
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById: function (id, data) {
        if (id == 3) {
            if (this._type == "bonus_1") {
                id = 301;
            } else if (this._type == "bonus_2") {
                id = 302;
            } else if (this._type == "bonus_3") {
                id = 303;
            }
        }
        this._super(id, data)
        this.hideAllIcon();
        if (data) {
            if (data.coin) {
                this.setCoin(data.coin)
            } else if (data.jackpot) {
                this.setJackpot(data.jackpot.id)
            }
        }
        this.setSymbolMask(true)
    },

    setSymbolMask(bMask) {
        if (this._type == "bonus_1" || this._type == "bonus_2" || this._type == "bonus_3") {
            let cfg = cc.vv.gameData.getGameCfg()
            if (cfg.symbol[this._id] && cfg.symbol[this._id].node) {
                let showNode = cc.find(cfg.symbol[this._id].node, this.node)
                if (bMask && cfg.symbol[this._id].isMask) {
                    showNode.color = new cc.Color(100, 100, 100);
                }
                else {
                    showNode.color = cc.Color.WHITE;
                }
            }
        }
    },

    //开始旋转时刻
    StartMove: function () {
        if (this._type == "bonus_1" || this._type == "bonus_2" || this._type == "bonus_3") {
        } else {
            this.setAnimationToTop(false)
        }
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx + this._reelIdx * 10;
    },

    // 隐藏所有特殊图标
    hideAllIcon() {
        this.setCoin();
        this.setJackpot();
    },

    setCoin(coin) {
        let lbl = cc.find("lbl", this.node);
        if (lbl) {
            if (coin) {
                lbl.active = true;
                lbl.getComponent(cc.Label).string = Global.formatNumShort(coin, 0);
            } else {
                lbl.active = false;
                lbl.getComponent(cc.Label).string = "";
            }
        }
    },

    setJackpot(id) {
        let jp = cc.find("jp", this.node);
        if (jp) {
            if (id) {
                jp.active = true;
                jp.getComponent("ImgSwitchCmp").setIndex(id - 1);
            } else {
                jp.active = false;
            }
        }
    },

    //播放win效果但又没有spin动画。自己写一个tween的action
    //先填写个默认的。
    playWinTweenAction() {
        this._showNode.stopAllActions()
        //记录原始缩放
        let nScale = this._showNode.scale
        this._showNodeOrgScale = nScale
        cc.tween(this._showNode)
            .repeatForever(cc.tween()
                .to(0.35, { scale: nScale + nScale * 0.2 })
                .to(0.35, { scale: nScale })
                .delay(1)
            )
            .start()
    },

    playBonusWinAnim() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id == 301 || id == 302 || id == 303) {
            if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].win_ani) {
                if (this._showNode) {
                    this._showNode.active = false
                }
                this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
                this._showNode.active = true
                this.node.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].win_ani.name, false)
                }
                // let winNode = cc.find(cfg.symbol[id].win_node, this.node);
                // winNode.active = true;
                // winNode.getComponent(cc.Animation).play(cfg.symbol[id].win_ani.name);
                // winNode.getComponent(cc.Animation).off("stop");
                // winNode.getComponent(cc.Animation).on("stop",()=>{winNode.active = false});
            }
        }
    },

    playBonusIdleAnim() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id == 301 || id == 302 || id == 303) {
            if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani) {
                if (this._showNode) {
                    this._showNode.active = false
                }
                this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
                this._showNode.active = true
                this.node.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].idle_ani.name, true)
                }
                // let winNode = cc.find(cfg.symbol[id].win_node, this.node);
                // winNode.active = true;
                // winNode.getComponent(cc.Animation).play(cfg.symbol[id].idle_ani.name);
                // winNode.getComponent(cc.Animation).off("stop");
                // winNode.getComponent(cc.Animation).on("stop",()=>{winNode.active = false});
            }
        }
    },

    playBonusStopAnim() {
        return new Promise(async (success, failed) => {
            let id = this._id
            let cfg = cc.vv.gameData.getGameCfg()
            let bonusIds = cfg.bonusIds;
            if (id == 3 || bonusIds.includes(id)) {
                if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani) {
                    if (this._showNode) {
                        this._showNode.active = false
                    }
                    this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
                    this._showNode.active = true
                    this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                    let nodeSp = this._showNode.getComponent(sp.Skeleton)
                    if (nodeSp) {
                        nodeSp.setAnimation(0, cfg.symbol[id].stop_ani.name, false);
                        nodeSp.getComponent(sp.Skeleton).setCompleteListener(() => {
                            nodeSp.getComponent(sp.Skeleton).setCompleteListener();
                            success();
                        })
                    }
                    // let winNode = cc.find(cfg.symbol[id].win_node, this.node);
                    // winNode.active = true;
                    // winNode.getComponent(cc.Animation).play(cfg.symbol[id].stop_ani.name);
                    //
                    // winNode.getComponent(cc.Animation).off("stop");
                    // winNode.getComponent(cc.Animation).on("stop", () => {
                    //     success();
                    // });
                }
            }
        });
    },

    playBonusShowAnim() {
        return new Promise(async (success, failed) => {
            let id = this._id
            let cfg = cc.vv.gameData.getGameCfg()
            let bonusIds = cfg.bonusIds;
            if (bonusIds.includes(id)) {
                if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].show_ani) {
                    if (this._showNode) {
                        this._showNode.active = false
                    }
                    this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
                    this._showNode.active = true
                    this.node.zIndex = cfg.symbol[id].show_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                    let nodeSp = this._showNode.getComponent(sp.Skeleton)
                    if (nodeSp) {
                        nodeSp.setAnimation(0, cfg.symbol[id].show_ani.name, false);
                        nodeSp.getComponent(sp.Skeleton).setCompleteListener(() => {
                            nodeSp.getComponent(sp.Skeleton).setCompleteListener();
                            success();
                        })
                    }
                    // let winNode = cc.find(cfg.symbol[id].win_node, this.node);
                    // winNode.active = true;
                    // winNode.getComponent(cc.Animation).play(cfg.symbol[id].show_ani.name);
                    //
                    // winNode.getComponent(cc.Animation).off("stop");
                    // winNode.getComponent(cc.Animation).on("stop", () => {
                    //     // if(cfg.symbol[id].idle_ani){
                    //     //     winNode.getComponent(cc.Animation).play(cfg.symbol[id].idle_ani.name);
                    //     // }
                    //     success();
                    // });
                }
            }
        });
    },

    getAnimationTop() {
        if (this._topAniNode) {
            let cloneNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s", this._symbolIdx, this._reelIdx), this._topAniNode);
            if (cloneNode) {
                return cloneNode;
            }
        }
        return null;
    },

    // update (dt) {},
});
